    "notes": "",
    "suggestedSolution": "### Flow\n1. Initialize a hash map to store seen numbers and their indices.\n2. Iterate through the array.\n3. For each number, calculate its complement (target - number).\n4. If complement exists in map, return [map[complement], current_index].\n5. Otherwise, add current number and index to map.\n\n### Intuition\nInstead of using two nested loops to check every pair, we can trade space for time. As we iterate, we just need to know \"have I seen the number that pairs with my current number to reach the target?\" A hash map gives us O(1) lookups to answer this instantly.\n\n### Brute Force\n- **Approach**: Two nested loops to check all possible pairs.\n- **Time Complexity**: O(n^2)\n- **Space Complexity**: O(1)\n\n### Optimal Solution\n```javascript\nfunction twoSum(nums, target) {\n    const map = new Map();\n    for (let i = 0; i < nums.length; i++) {\n        const complement = target - nums[i];\n        if (map.has(complement)) {\n            return [map.get(complement), i];\n        }\n        map.set(nums[i], i);\n    }\n    return [];\n}\n```\n- **Time Complexity**: O(n) - We traverse the list containing n elements exactly once.\n- **Space Complexity**: O(n) - The extra space required depends on the number of items stored in the hash table, which stores at most n elements.\n\n### Interview Tips\n- Clarify if the array is sorted (if yes, Two Pointers is O(1) space).\n- Clarify if there can be multiple solutions or no solutions.\n- Mention the time/space tradeoff explicitly to the interviewer.",
