    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Count the frequency of each number using a Hash Map.\n2. Create an array of arrays (buckets) where the index represents the frequency.\n3. Place each number into the bucket corresponding to its frequency.\n4. Iterate through the buckets from the end (highest frequency) to the beginning.\n5. Collect numbers until we have k elements.\n\n### Intuition\nNormally, finding top K elements suggests a Max Heap (O(n log k)). But because the maximum frequency of any element cannot exceed the length of the array (n), we can use Bucket Sort to achieve O(n) time!\n\n### Brute Force\n- **Approach**: Count frequencies, put into an array, and sort by frequency.\n- **Time Complexity**: O(n log n)\n- **Space Complexity**: O(n)\n\n### Optimal Solution (Bucket Sort)\n```javascript\nfunction topKFrequent(nums, k) {\n    const freqMap = new Map();\n    for (const num of nums) {\n        freqMap.set(num, (freqMap.get(num) || 0) + 1);\n    }\n    \n    const buckets = Array.from({ length: nums.length + 1 }, () => []);\n    \n    for (const [num, freq] of freqMap.entries()) {\n        buckets[freq].push(num);\n    }\n    \n    const result = [];\n    for (let i = buckets.length - 1; i >= 0 && result.length < k; i--) {\n        if (buckets[i].length > 0) {\n            result.push(...buckets[i]);\n        }\n    }\n    \n    return result;\n}\n```\n- **Time Complexity**: O(n) - We iterate through the array a constant number of times.\n- **Space Complexity**: O(n) - The map and buckets take O(n) space.\n\n### Interview Tips\n- The Bucket Sort trick relies on the fact that frequencies are bounded by `n`.\n- Be prepared to implement the Min-Heap solution (O(n log k)) if the interviewer specifically asks for it or restricts bucket sort.",
