    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Maintain a `candidate` and a `count` (Boyer-Moore Voting Algorithm).\n2. Iterate through the array.\n3. If `count` is 0, assign the current number to `candidate`.\n4. If current number equals `candidate`, increment `count`. Else, decrement `count`.\n5. Return `candidate`.\n\n### Intuition\nSince the majority element appears strictly more than n/2 times, its \"votes\" will always outweigh the combined votes of all other elements. Every time you see a different element, they cancel each other out, leaving the majority element in the end.\n\n### Brute Force\n- **Approach**: Hash map to count frequencies, then return max.\n- **Time/Space**: O(n) / O(n)\n\n### Optimal Solution\n```javascript\nfunction majorityElement(nums) {\n    let candidate = nums[0];\n    let count = 0;\n    for (let num of nums) {\n        if (count === 0) candidate = num;\n        count += (num === candidate ? 1 : -1);\n    }\n    return candidate;\n}\n```\n- **Time Complexity**: O(n)\n- **Space Complexity**: O(1)\n\n### Interview Tips\n- Mention the Hash Map approach first, then say \"we can optimize space using Boyer-Moore.\"",
    "r1": "2026-09-04T05:02:33.467Z",
    "r14": null
