    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Iterate through the array.\n2. For each number, mark its corresponding index (num - 1) as negative to indicate we've seen it.\n3. Iterate through the array again. Any index that is still positive means its corresponding number never appeared.\n\n### Intuition\nWe have an array of size `n` with numbers from `1` to `n`. We can use the array itself as a hash map by negating values at specific indices to flag that a number exists, achieving O(1) extra space.\n\n### Brute Force\n- **Approach**: Hash Set to check existence.\n- **Time/Space**: O(n) / O(n)\n\n### Optimal Solution\n```javascript\nfunction findDisappearedNumbers(nums) {\n    for (let i = 0; i < nums.length; i++) {\n        const index = Math.abs(nums[i]) - 1;\n        if (nums[index] > 0) nums[index] *= -1;\n    }\n    const res = [];\n    for (let i = 0; i < nums.length; i++) {\n        if (nums[i] > 0) res.push(i + 1);\n    }\n    return res;\n}\n```\n- **Time Complexity**: O(n)\n- **Space Complexity**: O(1) auxiliary\n\n### Interview Tips\n- The \"use the array itself as a hash map by negating values\" trick is very common for array problems bounded by `1...n`.",
