    "topic": "Arrays",
    "problem": "First Missing Positive",
    "slug": "first-missing-positive",
    "difficulty": "Hard",
    "roi": "★★★★☆",
    "company": "Google, Apple, Netflix",
    "targetMin": 20,
    "status": "Not Started",
    "attempts": 0,
    "actualMin": null,
    "firstSolve": null,
    "r3": null,
    "r7": null,
    "r21": null,
    "r45": null,
    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. We only care about numbers between `1` and `n`.\n2. Swap numbers into their correct \"sorted\" position (`nums[i]` should be at index `nums[i] - 1`).\n3. Iterate through the array and find the first index that doesn't have the correct number.\n4. Return `index + 1`.\n\n### Intuition\nThe answer MUST be between `1` and `n + 1`. By placing every valid number into its correct index (i.e. number 5 goes to index 4), we can just walk the array and find the first gap.\n\n### Brute Force\n- **Approach**: Sort or use a Hash Set.\n- **Time/Space**: O(n log n) or O(n) space.\n\n### Optimal Solution\n```javascript\nfunction firstMissingPositive(nums) {\n    let i = 0;\n    while (i < nums.length) {\n        let correctIdx = nums[i] - 1;\n        if (nums[i] > 0 && nums[i] <= nums.length && nums[i] !== nums[correctIdx]) {\n            [nums[i], nums[correctIdx]] = [nums[correctIdx], nums[i]];\n        } else {\n            i++;\n        }\n    }\n    for (i = 0; i < nums.length; i++) {\n        if (nums[i] !== i + 1) return i + 1;\n    }\n    return nums.length + 1;\n}\n```\n- **Time Complexity**: O(n) (Each number is swapped at most once)\n- **Space Complexity**: O(1)\n\n### Interview Tips\n- Cyclic Sort pattern is the key here."
