    "r7": null,
    "r21": null,
    "r45": null,
    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Create a hash map mapping each Roman symbol to its value.\n2. Iterate through the string.\n3. If the current symbol's value is less than the next symbol's value, subtract it.\n4. Otherwise, add it.\n\n### Intuition\nRoman numerals are usually written largest to smallest from left to right. When a smaller numeral appears before a larger one (like IV), it means subtraction.\n\n### Brute Force\n- **Approach**: Handle pairs of characters explicitly (e.g. \"IV\", \"IX\") and then single characters.\n- **Time/Space**: O(n) / O(1)\n\n### Optimal Solution\n```javascript\nfunction romanToInt(s) {\n    const map = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };\n    let total = 0;\n    for (let i = 0; i < s.length; i++) {\n        if (map[s[i]] < map[s[i+1]]) total -= map[s[i]];\n        else total += map[s[i]];\n    }\n    return total;\n}\n```\n- **Time Complexity**: O(n)\n- **Space Complexity**: O(1)\n\n### Interview Tips\n- Mention that this relies heavily on string iteration and simple lookaheads."
