    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Define a mapping of integer values to Roman symbols, sorted from largest to smallest (including edge cases like 900 -> CM).\n2. Iterate through the mapping.\n3. While the number is greater than or equal to the current mapping value, append the symbol and subtract the value.\n\n### Intuition\nWe want to use the largest possible symbols first to keep the string as short as possible. Greedy algorithm works perfectly here.\n\n### Optimal Solution\n```javascript\nfunction intToRoman(num) {\n    const val = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];\n    const sym = [\"M\", \"CM\", \"D\", \"CD\", \"C\", \"XC\", \"L\", \"XL\", \"X\", \"IX\", \"V\", \"IV\", \"I\"];\n    let res = \"\";\n    for (let i = 0; i < val.length && num > 0; i++) {\n        while (num >= val[i]) {\n            num -= val[i];\n            res += sym[i];\n        }\n    }\n    return res;\n}\n```\n- **Time Complexity**: O(1) (Bounded by the maximum Roman numeral size)\n- **Space Complexity**: O(1)\n\n### Interview Tips\n- Mention that this is a classic greedy problem."
