    "suggestedSolution": "### Flow\n1. Use three pointers, starting from the END of the arrays.\n2. Compare elements from `nums1` and `nums2` from back to front.\n3. Place the larger element at the very end of `nums1`.\n4. If elements from `nums2` remain, copy them over.\n\n### Intuition\nSince `nums1` has extra space at the end, iterating backwards prevents us from overwriting elements in `nums1` that we haven't processed yet.\n\n### Optimal Solution\n```javascript\nfunction merge(nums1, m, nums2, n) {\n    let i = m - 1, j = n - 1, k = m + n - 1;\n    while (j >= 0) {\n        if (i >= 0 && nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n}\n```\n- **Time Complexity**: O(n + m)\n- **Space Complexity**: O(1)\n\n### Interview Tips\n- Backwards iteration is a very common trick when merging into an existing array."
