    "suggestedSolution": "### Flow\n1. Put all elements of `nums1` into a Hash Set.\n2. Iterate through `nums2`. If an element is in the set, add it to results and remove it from the set (to avoid duplicates).\n\n### Intuition\nHash Sets give us O(1) lookups and naturally handle uniqueness.\n\n### Optimal Solution\n```javascript\nfunction intersection(nums1, nums2) {\n    const set1 = new Set(nums1);\n    const res = [];\n    for (let num of nums2) {\n        if (set1.has(num)) {\n            res.push(num);\n            set1.delete(num); // Avoid duplicates in result\n        }\n    }\n    return res;\n}\n```\n- **Time Complexity**: O(n + m)\n- **Space Complexity**: O(n)\n\n### Interview Tips\n- Clarify if duplicates are allowed in the output (this problem says no)."
