    "notes": "",
    "suggestedSolution": "### Flow\n1. Maintain a running `prefixSum`.\n2. Use a Hash Map to store the *remainder* of `prefixSum % k` and its earliest index.\n3. If we see the same remainder again at an index at least 2 steps away, we found a valid subarray.\n\n### Intuition\nIf two prefix sums have the same remainder when divided by `k`, the difference between those sums is a multiple of `k`.\n\n### Optimal Solution\n```javascript\nfunction checkSubarraySum(nums, k) {\n    const map = new Map();\n    map.set(0, -1); // Handle subarrays starting at index 0\n    let sum = 0;\n    \n    for (let i = 0; i < nums.length; i++) {\n        sum += nums[i];\n        let rem = k === 0 ? sum : sum % k;\n        \n        if (map.has(rem)) {\n            if (i - map.get(rem) > 1) return true;\n        } else {\n            map.set(rem, i);\n        }\n    }\n    return false;\n}\n```\n- **Time Complexity**: O(n)\n- **Space Complexity**: O(n)\n\n### Interview Tips\n- Focus on the math trick: `a % k == b % k` implies `(a - b) % k == 0`."
