    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Traverse array, track first occurrence, last occurrence, and frequency for each element in maps.\n2. Find the maximum frequency (the degree).\n3. Find the minimum length `(last - first + 1)` among elements with that max frequency.\n\n### Intuition\nThe shortest subarray containing the maximum frequency of an element MUST start at its first occurrence and end at its last occurrence.\n\n### Optimal Solution\n```javascript\nfunction findShortestSubArray(nums) {\n    const first = new Map(), last = new Map(), count = new Map();\n    let maxFreq = 0;\n    \n    for (let i = 0; i < nums.length; i++) {\n        let x = nums[i];\n        if (!first.has(x)) first.set(x, i);\n        last.set(x, i);\n        count.set(x, (count.get(x) || 0) + 1);\n        maxFreq = Math.max(maxFreq, count.get(x));\n    }\n    \n    let minLen = nums.length;\n    for (let [x, c] of count.entries()) {\n        if (c === maxFreq) {\n            minLen = Math.min(minLen, last.get(x) - first.get(x) + 1);\n        }\n    }\n    return minLen;\n}\n```\n- **Time/Space**: O(n) / O(n)\n\n### Interview Tips\n- This is purely a hash map bookkeeping problem."
