    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Calculate the total sum of the array.\n2. Iterate through, maintaining a `leftSum`.\n3. The right sum is exactly `totalSum - leftSum - nums[i]`.\n4. If they match, return the index.\n\n### Intuition\nBy precomputing the total sum, we avoid having to repeatedly scan the right side of the array.\n\n### Optimal Solution\n```javascript\nfunction pivotIndex(nums) {\n    let total = nums.reduce((a, b) => a + b, 0);\n    let left = 0;\n    \n    for (let i = 0; i < nums.length; i++) {\n        if (left === total - left - nums[i]) return i;\n        left += nums[i];\n    }\n    return -1;\n}\n```\n- **Time/Space**: O(n) / O(1)\n\n### Interview Tips\n- Mention that this is essentially a prefix sum problem with O(1) space."
