    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Calculate the expected sum of numbers from `0` to `n` using Gauss' formula: `n * (n + 1) / 2`.\n2. Calculate the actual sum of the array.\n3. The difference is the missing number.\n\n### Intuition\nMath provides an O(1) space solution. Alternatively, XOR-ing all numbers from 0 to n and XOR-ing with the array elements cancels out everything except the missing number.\n\n### Optimal Solution\n```javascript\nfunction missingNumber(nums) {\n    let n = nums.length;\n    let expected = (n * (n + 1)) / 2;\n    let actual = nums.reduce((a, b) => a + b, 0);\n    return expected - actual;\n}\n```\n- **Time/Space**: O(n) / O(1)\n\n### Interview Tips\n- Mention the Bit Manipulation (XOR) approach as an alternative to prevent integer overflow in lower-level languages."
