    "notes": "",
    "suggestedSolution": "### Flow\n1. Keep track of both the maximum and minimum product ending at the current element.\n2. When encountering a negative number, the max and min swap (since min * neg = max).\n3. Update the global max.\n\n### Intuition\nBecause multiplying by a negative number flips the sign, a highly negative product can instantly become a highly positive one. Thus, tracking the minimum (most negative) is essential.\n\n### Optimal Solution\n```javascript\nfunction maxProduct(nums) {\n    let res = nums[0], max = nums[0], min = nums[0];\n    for (let i = 1; i < nums.length; i++) {\n        let temp = max;\n        max = Math.max(nums[i], max * nums[i], min * nums[i]);\n        min = Math.min(nums[i], temp * nums[i], min * nums[i]);\n        res = Math.max(res, max);\n    }\n    return res;\n}\n```\n- **Time/Space**: O(n) / O(1)\n\n### Interview Tips\n- This is a trickier variation of Kadane's algorithm."
