    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Use the first row and first column as markers.\n2. If `matrix[i][j]` is 0, set `matrix[i][0] = 0` and `matrix[0][j] = 0`.\n3. Use a separate variable to track if the very first row/col need to be zeroed.\n4. Iterate and update matrix based on markers.\n\n### Intuition\nInstead of allocating O(m+n) space to remember which rows and columns to zero, we can just store that information directly in the first row and column of the matrix itself.\n\n### Optimal Solution\n```javascript\nfunction setZeroes(matrix) {\n    let col0 = 1, rows = matrix.length, cols = matrix[0].length;\n    \n    for (let i = 0; i < rows; i++) {\n        if (matrix[i][0] === 0) col0 = 0;\n        for (let j = 1; j < cols; j++) {\n            if (matrix[i][j] === 0) matrix[i][0] = matrix[0][j] = 0;\n        }\n    }\n    \n    for (let i = rows - 1; i >= 0; i--) {\n        for (let j = cols - 1; j >= 1; j--) {\n            if (matrix[i][0] === 0 || matrix[0][j] === 0) matrix[i][j] = 0;\n        }\n        if (col0 === 0) matrix[i][0] = 0;\n    }\n}\n```\n- **Time/Space**: O(m*n) / O(1)\n\n### Interview Tips\n- Constant space is the entire point of this problem."
