    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Maintain boundaries: top, bottom, left, right.\n2. Traverse right, update top boundary. Traverse down, update right boundary. Traverse left, update bottom. Traverse up, update left.\n3. Repeat until boundaries overlap.\n\n### Intuition\nIt's just simulation with careful boundary checking.\n\n### Optimal Solution\n```javascript\nfunction spiralOrder(matrix) {\n    const res = [];\n    let top = 0, bottom = matrix.length - 1;\n    let left = 0, right = matrix[0].length - 1;\n    \n    while (top <= bottom && left <= right) {\n        for (let i = left; i <= right; i++) res.push(matrix[top][i]);\n        top++;\n        for (let i = top; i <= bottom; i++) res.push(matrix[i][right]);\n        right--;\n        if (top <= bottom) {\n            for (let i = right; i >= left; i--) res.push(matrix[bottom][i]);\n            bottom--;\n        }\n        if (left <= right) {\n            for (let i = bottom; i >= top; i--) res.push(matrix[i][left]);\n            left++;\n        }\n    }\n    return res;\n}\n```\n- **Time/Space**: O(m*n) / O(1) auxiliary\n\n### Interview Tips\n- Edge cases: Matrix with 1 row or 1 column. The inner `if` conditions handle this."
