    "notes": "",
    "suggestedSolution": "### Flow\n1. Reverse the entire array.\n2. Reverse the first `k` elements.\n3. Reverse the remaining `n-k` elements.\n\n### Intuition\nRotation moves elements from the end to the front. Reversing the whole array puts them in the front but backward. Reversing them in chunks fixes their order!\n\n### Optimal Solution\n```javascript\nfunction rotate(nums, k) {\n    k %= nums.length;\n    const reverse = (l, r) => {\n        while (l < r) {\n            [nums[l], nums[r]] = [nums[r], nums[l]];\n            l++; r--;\n        }\n    }\n    reverse(0, nums.length - 1);\n    reverse(0, k - 1);\n    reverse(k, nums.length - 1);\n}\n```\n- **Time/Space**: O(n) / O(1)\n\n### Interview Tips\n- Always modulo `k` by `n` to handle cases where `k` is larger than the array size!"
