    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Use Floyd's Tortoise and Hare (Cycle Detection).\n2. Phase 1: Move slow by 1, fast by 2 until they intersect.\n3. Phase 2: Put one pointer at the start. Move both by 1. Where they intersect is the duplicate.\n\n### Intuition\nTreat the array values as pointers to indices. Since there is a duplicate, multiple indices point to the same value, creating a cycle.\n\n### Optimal Solution\n```javascript\nfunction findDuplicate(nums) {\n    let slow = nums[0], fast = nums[nums[0]];\n    while (slow !== fast) {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    }\n    slow = 0;\n    while (slow !== fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n    return slow;\n}\n```\n- **Time/Space**: O(n) / O(1)\n\n### Interview Tips\n- This problem restricts modifying the array and demands O(1) space, making cycle detection the only valid O(n) solution."
