    "suggestedSolution": "### Flow\n1. Push all Gates (0) into a BFS queue.\n2. Run Multi-Source BFS.\n3. For each popped cell, check its 4 neighbors.\n4. If neighbor is an empty room (INF), its distance is `current_distance + 1`. Update the grid and push to queue.\n\n### Intuition\nInstead of running BFS from every single room to find a gate (O( (M*N)^2 )), start at ALL gates simultaneously and radiate outwards.\n\n### Optimal Solution (Multi-Source BFS)\n- **Time/Space**: O(M*N) / O(M*N)\n\n### Interview Tips\n- Identical logic to Rotting Oranges and 01 Matrix. Multi-source BFS is a mandatory pattern to learn.",
