    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Insert all words into a Hash Set for O(1) lookup.\n2. Push `[beginWord, 1]` into a Queue.\n3. While queue is not empty, pop word.\n4. Generate all possible mutations (change each char from 'a' to 'z').\n5. If mutation == endWord, return steps + 1.\n6. If mutation is in set, delete from set (mark visited) and push to queue.\n\n### Intuition\nShortest path from A to B in an unweighted graph is ALWAYS found using BFS. DFS will explore massive useless paths and TLE.\n\n### Optimal Solutions\n\n#### 1. BFS\n- Generate mutations: `word.length * 26` checks.\n- **Time/Space**: O(M^2 * N) where M is word length, N is word list size. (M^2 because string slicing takes O(M)).\n\n#### 2. Bi-directional BFS\nRun BFS simultaneously from `beginWord` and `endWord`. Expand whichever queue is smaller. Drastically reduces search space.\n\n### Interview Tips\n- Interviewers love asking how to optimize this -> Bi-directional BFS is the golden answer."
