    "suggestedSolution": "### Flow\n1. Use a Hash Set for `deadends` and visited states.\n2. Initialize BFS queue with `['0000', 0]`.\n3. Pop state. If it's the target, return turns.\n4. Generate 8 adjacent states (turn each of the 4 dials up or down by 1).\n5. If state not in visited/deadends, add to visited and push to queue.\n\n### Intuition\nAnother classic \"Shortest Path in Unweighted Graph\" -> BFS. The graph is implicit, generated on the fly by turning dials.\n\n### Optimal Solution (BFS)\nGenerating neighbors:\nFor each of the 4 digits, add 1 (wrap 9->0) and subtract 1 (wrap 0->9).\n- **Time/Space**: O(10^4) / O(10^4) since there are exactly 10,000 possible combinations.\n\n### Interview Tips\n- String manipulation in JS can be slow. Splitting into an array of characters, modifying, and joining is the standard way."
