    "problem": "Network Delay Time",
    "slug": "network-delay-time",
    "difficulty": "Medium",
    "roi": "★★★★★",
    "company": "Google, Amazon, Uber",
    "targetMin": 28,
    "status": "Solved",
    "attempts": 0,
    "actualMin": null,
    "firstSolve": "2026-09-02T14:42:19.626Z",
    "r3": null,
    "r7": null,
    "r21": null,
    "r45": null,
    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Build an adjacency list of `[neighbor, weight]`.\n2. Run Dijkstra's Algorithm from node `k`.\n3. Track the shortest time to reach every node.\n4. The result is the max time in the shortest-paths array. If any node is unreachable, return -1.\n\n### Intuition\nFinding the shortest time for a signal to reach all nodes in a weighted directed graph is the exact definition of the Single-Source Shortest Path problem, best solved by Dijkstra.\n\n### Optimal Solutions\n\n#### 1. Dijkstra (Min-Heap)\n```javascript\nfunction networkDelayTime(times, n, k) {\n    const adj = Array.from({length: n + 1}, () => []);\n    for (const [u, v, w] of times) adj[u].push([v, w]);\n    \n    const dist = new Array(n + 1).fill(Infinity);\n    dist[k] = 0;\n    // JS doesn't have built-in PriorityQueue. Use an array and sort, or implement MinHeap.\n    // Assuming a MinPriorityQueue exists:\n    const pq = new MinPriorityQueue({ priority: x => x.dist });\n    pq.enqueue({node: k, dist: 0});\n    \n    while (!pq.isEmpty()) {\n        const {node: u, dist: d} = pq.dequeue().element;\n        if (d > dist[u]) continue;\n        for (const [v, w] of adj[u]) {\n            if (dist[u] + w < dist[v]) {\n                dist[v] = dist[u] + w;\n                pq.enqueue({node: v, dist: dist[v]});\n            }\n        }\n    }\n    \n    let max = Math.max(...dist.slice(1));\n    return max === Infinity ? -1 : max;\n}\n```\n- **Time/Space**: O(E log V) / O(V + E)\n\n#### 2. Bellman-Ford\nInitialize distance array to Infinity. Loop `V-1` times. In each loop, iterate over all edges `(u,v,w)` and relax: `dist[v] = Math.min(dist[v], dist[u] + w)`.\n- **Time/Space**: O(V * E) / O(V). Often easier to code in JS since there's no native Heap.\n\n### Interview Tips\n- Mention that Dijkstra is faster, but since JS lacks a PriorityQueue, Bellman-Ford is much faster to physically type out in an interview if V/E are small.",
