    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Use DSU. Each email is mapped to an ID. Alternatively, use DFS/BFS treating emails as nodes and linking emails in the same account.\n2. Group emails by their root parent (DSU) or connected component (DFS).\n3. Sort the grouped emails.\n4. Prepend the Account Name.\n\n### Intuition\nIf two accounts share an email, they belong to the same person. This implies transitive relations (A shares with B, B shares with C -> A shares with C). This is a graph connectivity problem!\n\n### Optimal Solutions\n\n#### 1. DSU on Emails\nMap each unique email to a numeric ID (or just map email strings to parent email strings). Iterate through accounts, unioning all emails in an account to the first email. Group by finding the root.\n- **Time/Space**: O(NK log(NK)) due to sorting emails / O(NK)\n\n#### 2. DFS on Adjacency List\nBuild graph: an edge exists between the first email of an account and all other emails in that account. Run DFS to find components.\n\n### Interview Tips\n- String mapping in DSU can be tricky. It's often easier to map strings to integers first to build a standard array-based DSU."
