    "r7": null,
    "r21": null,
    "r45": null,
    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. View each stone as a node. An edge exists if two stones share the same row OR the same column.\n2. Find the number of connected components in this graph.\n3. The maximum stones you can remove is exactly `Total Stones - Number of Components`.\n\n### Intuition\nIf you have a group of stones connected by rows/cols, you can always remove all of them except for exactly ONE stone (the last anchor). Thus, each connected component leaves exactly 1 stone behind.\n\n### Optimal Solutions\n\n#### 1. DFS\nBuild adjacency list where `i` connects to `j` if they share a row/col. Count components.\n- **Time/Space**: O(N^2) / O(N^2)\n\n#### 2. DSU on Coordinates (Highly Optimized)\nUnion the row coordinate and the column coordinate for each stone! To prevent collision between row 0 and col 0, offset the columns (e.g. `col + 10000`).\n- **Time/Space**: O(N) / O(MaxRow + MaxCol)\n\n### Interview Tips\n- The mathematical realization (`ans = N - components`) is 90% of the interview."
