    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Build a directed graph. A directed edge `i -> j` exists if the distance between bomb `i` and `j` is <= the radius of bomb `i`. (Note: this is NOT symmetric!).\n2. For each bomb, run DFS/BFS to find how many total bombs it can reach.\n3. Return the maximum count.\n\n### Intuition\nA bomb detonating another bomb is a directed graph traversal. Since radii differ, bomb A might reach B, but B might not reach A.\n\n### Optimal Solution (DFS/BFS)\n```javascript\n// Distance squared <= Radius squared\nconst distSq = (x1-x2)**2 + (y1-y2)**2;\n```\n- Build adj list O(N^2).\n- Run DFS from *every* node O(N * (V+E)) = O(N^3).\n- Since N <= 100, O(N^3) is perfectly fine.\n\n### Interview Tips\n- Using `distance squared` avoids slow and inaccurate floating-point `Math.sqrt()` operations. Always do this for distance checks!"
