    "r3": null,
    "r7": null,
    "r21": null,
    "r45": null,
    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. A node is safe if every possible path starting from it leads to a terminal node (no outgoing edges).\n2. Use DFS with 3 states: 0 (unvisited), 1 (visiting - unsafe/cycle), 2 (visited - safe).\n3. If DFS encounters a node in state 1, it's a cycle. If any child is unsafe, the parent is unsafe.\n\n### Intuition\nThis is just Cycle Detection in a directed graph. Any node that is part of a cycle, or can reach a cycle, is NOT safe. \n\n### Optimal Solutions\n\n#### 1. DFS Cycle Detection\nReturn true if safe. Memoize results in an array.\n- **Time/Space**: O(V + E) / O(V)\n\n#### 2. Topological Sort (Reverse Kahn's)\nReverse all edges in the graph! Now, terminal nodes have in-degree 0. Run Kahn's algorithm. Any node processed by Kahn's is safe!\n- **Time/Space**: O(V + E) / O(V + E)\n\n### Interview Tips\n- The reverse Kahn's approach is brilliant and shows deep understanding of topological sorting."
