    "explain": 0,
    "mistakeTag": "",
    "notes": "",
    "suggestedSolution": "### Flow\n1. Build an adjacency list and in-degree map for all unique characters.\n2. Compare adjacent words. Find the FIRST differing character. Add a directed edge `char1 -> char2`.\n3. Run Topological Sort (Kahn's or DFS).\n4. If a cycle exists, return \"\". Else return the sorted characters.\n\n### Intuition\nThe relative order of words only gives us information about the *first* differing character. This creates a directed dependency (char A must come before char B), making it a Topological Sort problem.\n\n### Optimal Solution (Kahn's BFS)\n1. Initialize inDegree to 0 for ALL unique characters present in words.\n2. Build graph. (Edge case: `\"abc\", \"ab\"` is invalid, return \"\").\n3. Push inDegree 0 to Queue.\n4. Process queue, append to result.\n5. If result length !== unique characters, return \"\".\n\n- **Time/Space**: O(C) where C is total length of all words / O(1) space since max 26 characters.\n\n### Interview Tips\n- Hardest part is building the graph correctly. Remember to initialize in-degrees for characters that have NO dependencies!"
