        strategies: [
          "Base Case: When your current state represents a valid solution, add a *copy* of it to your results.",
          "Iterate Choices: Loop through all possible next moves.",
          "Choose-Explore-Unchoose: Add the choice to your state -> recurse -> remove the choice from your state."
        ],
        exampleFlow: `public void backtrack(List<List<Integer>> res, List<Integer> temp, int[] nums, int start) {
    res.add(new ArrayList<>(temp)); // Base case / Collect
    for (int i = start; i < nums.length; i++) {
        temp.add(nums[i]); // Choose
        backtrack(res, temp, nums, i + 1); // Explore
        temp.remove(temp.size() - 1); // Unchoose
    }
}`
