        exampleFlow: `// 1. Recursion
int solve(int i, int j, int[][] grid) {
    if(i == 0 && j == 0) return grid[0][0];
    if(i < 0 || j < 0) return 1e9; // Out of bounds
    int up = grid[i][j] + solve(i-1, j, grid);
    int left = grid[i][j] + solve(i, j-1, grid);
    return Math.min(up, left);
}

// 2. Memoization
int solveMemo(int i, int j, int[][] grid, int[][] dp) {
    if(i == 0 && j == 0) return grid[0][0];
    if(i < 0 || j < 0) return 1e9;
    if(dp[i][j] != -1) return dp[i][j];
    int up = grid[i][j] + solveMemo(i-1, j, grid, dp);
    int left = grid[i][j] + solveMemo(i, j-1, grid, dp);
    return dp[i][j] = Math.min(up, left);
}

// 3. Tabulation
int[][] dp = new int[m][n];
for(int i = 0; i < m; i++){
    for(int j = 0; j < n; j++){
        if(i == 0 && j == 0) dp[i][j] = grid[i][j];
        else {
            int up = grid[i][j] + (i > 0 ? dp[i-1][j] : 1e9);
            int left = grid[i][j] + (j > 0 ? dp[i][j-1] : 1e9);
            dp[i][j] = Math.min(up, left);
        }
    }
}

// 4. Space Optimization (1D Array)
int[] prev = new int[n];
for(int i = 0; i < m; i++){
    int[] temp = new int[n];
    for(int j = 0; j < n; j++){
        if(i == 0 && j == 0) temp[j] = grid[i][j];
        else {
            int up = grid[i][j] + (i > 0 ? prev[j] : 1e9);
            int left = grid[i][j] + (j > 0 ? temp[j-1] : 1e9);
            temp[j] = Math.min(up, left);
        }
    }
    prev = temp;
}`
