        exampleFlow: `// 1. Recursion
int solve(int i, int j, String s1, String s2) {
    if(i == 0 || j == 0) return 0;
    if(s1.charAt(i-1) == s2.charAt(j-1)) return 1 + solve(i-1, j-1, s1, s2);
    return Math.max(solve(i-1, j, s1, s2), solve(i, j-1, s1, s2));
}

// 2. Memoization
int solveMemo(int i, int j, String s1, String s2, int[][] dp) {
    if(i == 0 || j == 0) return 0;
    if(dp[i][j] != -1) return dp[i][j];
    if(s1.charAt(i-1) == s2.charAt(j-1)) return dp[i][j] = 1 + solveMemo(i-1, j-1, s1, s2, dp);
    return dp[i][j] = Math.max(solveMemo(i-1, j, s1, s2, dp), solveMemo(i, j-1, s1, s2, dp));
}

// 3. Tabulation
int[][] dp = new int[n+1][m+1];
for(int i = 1; i <= n; i++){
    for(int j = 1; j <= m; j++){
        if(s1.charAt(i-1) == s2.charAt(j-1)) dp[i][j] = 1 + dp[i-1][j-1];
        else dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]);
    }
}

// 4. Space Optimization (1D Arrays)
int[] prev = new int[m+1];
for(int i = 1; i <= n; i++){
    int[] cur = new int[m+1];
    for(int j = 1; j <= m; j++){
        if(s1.charAt(i-1) == s2.charAt(j-1)) cur[j] = 1 + prev[j-1];
        else cur[j] = Math.max(prev[j], cur[j-1]);
    }
    prev = cur;
}`
