        name: "Graph: Shortest Path (Dijkstra, Bellman-Ford, Floyd-Warshall)",
        challenge: "You need to find the shortest path in a weighted graph (where edges have different costs).",
        analogy: "Using Google Maps. You want the fastest route. Dijkstra always picks the next closest town to explore (Greedy).",
        problems: [
          { name: "Network Delay Time (Dijkstra)", url: "https://leetcode.com/problems/network-delay-time/" },
          { name: "Cheapest Flights Within K Stops", url: "https://leetcode.com/problems/cheapest-flights-within-k-stops/" },
          { name: "Path With Minimum Effort", url: "https://leetcode.com/problems/path-with-minimum-effort/" }
        ],
        strategies: [
          "Dijkstra (Positive weights): Use a PriorityQueue (Min-Heap) ordered by distance. Always pop the minimum distance node.",
          "Bellman-Ford (Negative weights): Relax all edges N-1 times. If distances change on the Nth time, there is a negative cycle.",
          "Floyd-Warshall (All-Pairs): 3 nested loops checking if path \`i -> k -> j\` is shorter than \`i -> j\`."
        ],
        exampleFlow: `// Dijkstra's Algorithm
PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> x[1] - y[1]); // {node, distance}
int[] dist = new int[N];
Arrays.fill(dist, Integer.MAX_VALUE);
dist[start] = 0;
pq.offer(new int[]{start, 0});

while(!pq.isEmpty()){
    int[] curr = pq.poll();
    int node = curr[0];
    int d = curr[1];
    
    if (d > dist[node]) continue; // Optimization
    
    for(int[] adj : graph.get(node)){
        int nextNode = adj[0];
        int weight = adj[1];
        if(d + weight < dist[nextNode]){
            dist[nextNode] = d + weight;
            pq.offer(new int[]{nextNode, dist[nextNode]});
        }
    }
}`
