        imageUrl: "/lld_composite.jpg",
        challenge: "You have nested structures where items contain other items of the exact same type (e.g., a Folder contains Files, but also contains other Folders). You need to calculate the total size, but writing loops for infinite nesting is difficult.",
        analogy: "Opening Russian nesting dolls. You don't know how many dolls are inside. You need a single rule that applies to every doll, whether it's the biggest one or the tiniest solid one.",
        strategies: [
          "Composite Pattern: Create a common `FileSystemNode` interface with a `getSize()` method. Both `File` (leaf) and `Folder` (composite) implement it. When you call `getSize()` on a Folder, it iterates through its children and calls `getSize()` on them recursively.",
          "Iterator Pattern: Provide a standard way to traverse the entire tree (e.g., Depth-First or Breadth-First) without exposing the underlying arrays or lists to the client."
        ],
        exampleFlow: "Client requests `folder.getSize()` -> Folder loops through children: if child is File, add its size. If child is Folder, call its `getSize()` -> Returns total."
